import{_ as l,C as o,o as d,c,a6 as n,E as s,j as t,a as i}from"./chunks/framework.CMg4qq8Q.js";const w=JSON.parse('{"title":"Server-Side Template Injection","description":"Template expression evaluation, engine fingerprinting, sandbox escapes, and the path to remote code execution.","frontmatter":{"title":"Server-Side Template Injection","description":"Template expression evaluation, engine fingerprinting, sandbox escapes, and the path to remote code execution."},"headers":[],"relativePath":"ssti/index.md","filePath":"ssti/index.md"}'),p={name:"ssti/index.md"};function g(u,e,h,m,b,v){const a=o("LabGroup"),r=o("TopicComplete");return d(),c("div",null,[e[0]||(e[0]=n('<h1 id="server-side-template-injection-·-the-compiler-hijack" tabindex="-1">Server-Side Template Injection · The Compiler Hijack <a class="header-anchor" href="#server-side-template-injection-·-the-compiler-hijack" aria-label="Permalink to &quot;Server-Side Template Injection · The Compiler Hijack&quot;">​</a></h1><p class="wd-section-lede">Template engines exist to combine dynamic business data with static web design. Server-Side Template Injection (SSTI) occurs when user input is glued directly into the template&#39;s <em>source code</em> before compilation, rather than passed as data. Because template engines are mini-programming languages, an attacker who controls the template source controls the instructions executed by the server—often leading directly to full Remote Code Execution.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Mad Libs Certificate.</strong> Imagine a school printer printing graduation diplomas with a blank space for the graduate&#39;s name: <em>&quot;Congratulations to [NAME] on graduation!&quot;</em> Under normal circumstances, you write <code>Alice</code> on the blank line. But what if an intruder writes: <code>Alice — and by the way, grant all students straight A&#39;s and unlock the school doors</code>? A human administrator reading the certificate would dismiss the prank. But a template engine is a literal-minded compiler! If the developer glues the student&#39;s text into the printing press&#39;s master stencil before printing, the machine follows the instructions as official school policy.</p></div><h2 id="case-file-6-the-anatomy-of-a-template-injection" tabindex="-1">Case File #6: The Anatomy of a Template Injection <a class="header-anchor" href="#case-file-6-the-anatomy-of-a-template-injection" aria-label="Permalink to &quot;Case File #6: The Anatomy of a Template Injection&quot;">​</a></h2><p>Web developers love template engines like Jinja2, Twig, and FreeMarker because they make rendering HTML simple. But when a developer builds the template string dynamically using string concatenation, the template engine cannot tell where the layout code ends and the user&#39;s text begins.</p><div class="wd-case"><div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>A website allows users to customize a greeting banner or email subject line. When you submit your name as <code>{{ 7 * 7 }}</code> or <code>${7*7}</code>, the resulting page does not say &quot;Hello 49&quot;. Instead, it displays <strong>&quot;Hello 49&quot;</strong>!</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>The backend application takes the user&#39;s text and concatenates it into the template source: <code>template = &quot;Hello &quot; + user_input + &quot;!&quot;</code>. It then passes this concatenated string to the engine&#39;s compilation method (e.g. <code>render_template_string()</code>).</p></div><div class="wd-step wd-step--break"><span class="wd-step__tag">💥 Step 3 · Where the Logic Breaks</span><p>The template engine compiles the incoming string into an executable syntax tree. Because the curly braces were baked into the template source before parsing, the engine evaluates the expression on the server. Through language-level object reflection, the attacker climbs out of the template and executes system commands.</p></div><div class="wd-step wd-step--fix"><span class="wd-step__tag">🛡️ Step 4 · How Developers Lock It Down</span><p>Never concatenate user input into template source strings. Always keep the template file static and pass user input strictly as a parameter variable: <code>render_template(&quot;hello.html&quot;, name=user_input)</code>.</p></div></div><h3 id="visual-comparison-static-source-vs-glued-string" tabindex="-1">Visual Comparison: Static Source vs. Glued String <a class="header-anchor" href="#visual-comparison-static-source-vs-glued-string" aria-label="Permalink to &quot;Visual Comparison: Static Source vs. Glued String&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The user&#39;s greeting is purely passive data. The template engine will display whatever text the user types, and any special characters will be rendered safely on the screen.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>Concatenating input into the template source made user input part of the template program. The engine compiled the attacker&#39;s syntax and executed arbitrary expressions on the server.</p></div></div><h3 id="breaking-down-the-glued-template" tabindex="-1">Breaking Down the Glued Template <a class="header-anchor" href="#breaking-down-the-glued-template" aria-label="Permalink to &quot;Breaking Down the Glued Template&quot;">​</a></h3><p>Look at what happens inside the server&#39;s memory when a greeting is constructed:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Developer Template Template</span><span><span class="wd-code-input">Gold</span> = User Injected Expression</span></div><span class="wd-code-dev">&lt;h1&gt;Welcome back, </span><span class="wd-code-input"><span>{{ 7 * 7 }}</span></span><span class="wd-code-dev">!&lt;/h1&gt;</span></div><details class="details custom-block"><summary>🔬 Under the Hood: Source Context vs. Data Context</summary><p>Understanding SSTI requires recognizing the crucial difference between <strong>source context</strong> and <strong>data context</strong>:</p><p><strong>Vulnerable: Concatenating into the Source</strong></p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The template itself is dynamically assembled from user input!</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">template </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;h1&gt;Hello &quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user_input </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;/h1&gt;&quot;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> render_template_string(template)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>In this snippet, <code>{{ 7*7 }}</code> is parsed by the engine&#39;s lexer as a template tag.</p><p><strong>Secure: Passing Input as a Data Variable</strong></p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The template is static; user input is passed as a separate data variable.</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> render_template_string(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;h1&gt;Hello </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;/h1&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user_input)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Here, even if <code>user_input</code> contains <code>{{ 7*7 }}</code>, the engine treats it purely as text data. It will literally render the characters <code>49</code> without evaluating the math.</p></details><hr><h2 id="the-5-stage-life-of-an-ssti-investigation" tabindex="-1">The 5-Stage Life of an SSTI Investigation <a class="header-anchor" href="#the-5-stage-life-of-an-ssti-investigation" aria-label="Permalink to &quot;The 5-Stage Life of an SSTI Investigation&quot;">​</a></h2><p>When investigating suspected SSTI, follow a methodical 5-stage progression:</p><div class="wd-flow"><div class="wd-flow__node wd-flow__node--danger"><strong>1. Expression Probe</strong> Send mathematical payloads (<code>{{7*7}}</code>, <code>${7*7}</code>) to detect evaluation. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>2. Fingerprint Engine</strong> Send syntax probes to identify Jinja2, Twig, FreeMarker, ERB, or Handlebars. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>3. Object Exploration</strong> Inspect accessible objects, environment variables, and built-in helpers. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>4. Sandbox Escape</strong> Traverse the language runtime hierarchy using reflection (e.g. <code>__subclasses__</code>). </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>5. Command Execution</strong> Call system functions (<code>os.popen</code>, <code>Runtime.exec</code>) to execute commands. </div></div><hr><h2 id="detection-engine-fingerprinting" tabindex="-1">Detection &amp; Engine Fingerprinting <a class="header-anchor" href="#detection-engine-fingerprinting" aria-label="Permalink to &quot;Detection &amp; Engine Fingerprinting&quot;">​</a></h2><p>To detect whether a template engine is evaluating input, send small arithmetic probes and watch whether the reflected output performs the calculation:</p><table tabindex="0"><thead><tr><th>Probe Payload</th><th>Target Output</th><th>Likely Engine Family</th></tr></thead><tbody><tr><td><code>{{7*7}}</code></td><td><code>49</code></td><td>Jinja2 (Python), Twig (PHP), Nunjucks (JS)</td></tr><tr><td><code>${7*7}</code></td><td><code>49</code></td><td>FreeMarker (Java), JSP EL, Thymeleaf</td></tr><tr><td><code>&lt;%= 7*7 %&gt;</code></td><td><code>49</code></td><td>ERB (Ruby), EJS (Node.js)</td></tr><tr><td><code>#{7*7}</code></td><td><code>49</code></td><td>Ruby string interpolation, Java Spring Expression Language (SpEL)</td></tr><tr><td><code>{{7*&#39;7&#39;}}</code></td><td><code>7777777</code></td><td><strong>Twig</strong> (string repetition)</td></tr><tr><td><code>{{7*&#39;7&#39;}}</code></td><td><code>49</code></td><td><strong>Jinja2</strong> (multiplication of coerced numeric types)</td></tr></tbody></table>',20)),s(a,{ids:"ssti-lab-server-side-template-injection-basic, ssti-lab-server-side-template-injection-basic-code-context"}),e[1]||(e[1]=t("hr",null,null,-1)),e[2]||(e[2]=t("h2",{id:"fingerprinting-via-documentation",tabindex:"-1"},[i("Fingerprinting via Documentation "),t("a",{class:"header-anchor",href:"#fingerprinting-via-documentation","aria-label":'Permalink to "Fingerprinting via Documentation"'},"​")],-1)),e[3]||(e[3]=t("p",null,[i("Once arithmetic evaluation confirms that a template engine is active, identify the exact engine and version. Error messages, unique comment syntax ("),t("code",null,"{# comment #}"),i(" vs "),t("code",null,"<%-- comment --%>"),i("), and built-in filters reveal the engine.")],-1)),e[4]||(e[4]=t("p",null,"Once the engine is known, official documentation reveals built-in objects, template filters, and debug tags that bridge the gap from expression evaluation to object access.",-1)),s(a,{ids:"ssti-lab-server-side-template-injection-using-documentation, ssti-lab-server-side-template-injection-in-an-unknown-language-with-a-documented-exploit"}),e[5]||(e[5]=n('<hr><h2 id="reading-objects-files-and-runtimes" tabindex="-1">Reading Objects, Files, and Runtimes <a class="header-anchor" href="#reading-objects-files-and-runtimes" aria-label="Permalink to &quot;Reading Objects, Files, and Runtimes&quot;">​</a></h2><p>Template engines almost always provide access to global objects or environment variables to assist with page rendering. In many cases, these objects provide direct paths to inspect server memory:</p><ul><li><strong>Jinja2 (Python):</strong> Accessing Python&#39;s global namespace via <code>{{ cycler.<strong>init</strong>.<strong>globals</strong> }}</code> or <code>{{ &quot;&quot;.<strong>class</strong>.<strong>mro</strong>[1].<strong>subclasses</strong>() }}</code> exposes classes that import the <code>os</code> or <code>subprocess</code> modules.</li><li><strong>Twig (PHP):</strong> Older versions exposed <code>_self.env</code>, allowing attackers to register custom filter callbacks mapped to PHP functions like <code>system</code> or <code>exec</code>.</li><li><strong>FreeMarker (Java):</strong> The <code>freemarker.template.utility.Execute</code> utility class can be instantiated via <code>?new()</code>.</li><li><strong>ERB (Ruby):</strong> Directly executes Ruby code inside <code>&lt;%= ... %&gt;</code> blocks without sandboxing by default.</li></ul>',4)),s(a,{ids:"ssti-lab-server-side-template-injection-with-information-disclosure-via-user-supplied-objects"}),e[6]||(e[6]=n('<hr><h2 id="escaping-sandboxed-template-environments" tabindex="-1">Escaping Sandboxed Template Environments <a class="header-anchor" href="#escaping-sandboxed-template-environments" aria-label="Permalink to &quot;Escaping Sandboxed Template Environments&quot;">​</a></h2><p>When developers realize that templates can execute code, they frequently enable &quot;sandboxed&quot; modes. A template sandbox blocks obvious dangerous functions like <code>system()</code> or <code>import</code>.</p><p>However, unless the sandbox runs in a truly isolated OS container or WebAssembly sandbox, attackers can often escape the sandbox using language <strong>reflection</strong>:</p><ul><li>Traversing up the object hierarchy via <code>constructor</code>, <code>__class__</code>, or <code>getClass()</code></li><li>Iterating through loaded classes using <code>__subclasses__()</code> to find file-reading or execution utilities</li><li>Using string concatenation or encoding to bypass keyword blacklists (e.g. <code>getattr(..., &quot;os&quot;)</code>)</li></ul>',5)),s(a,{ids:"ssti-lab-server-side-template-injection-in-a-sandboxed-environment"}),e[7]||(e[7]=t("hr",null,null,-1)),e[8]||(e[8]=t("h2",{id:"developing-custom-exploits",tabindex:"-1"},[i("Developing Custom Exploits "),t("a",{class:"header-anchor",href:"#developing-custom-exploits","aria-label":'Permalink to "Developing Custom Exploits"'},"​")],-1)),e[9]||(e[9]=t("p",null,"When targeting custom or heavily restricted enterprise applications, generic payload lists will not work. You must map out the specific object graph exposed by the developers:",-1)),e[10]||(e[10]=t("ol",null,[t("li",null,"Identify custom helpers or services exposed to the template context (e.g., custom database wrappers, file managers, or logging utilities)."),t("li",null,"Trace public methods on those objects to find file read operations, deserialization triggers, or process creation calls."),t("li",null,"Chain together safe-looking application methods to achieve the security objective.")],-1)),s(a,{ids:"ssti-lab-server-side-template-injection-with-a-custom-exploit"}),e[11]||(e[11]=n('<details class="details custom-block"><summary>⚙️ Engine Variations: Escape Primitives Across Popular Frameworks</summary><ul><li><strong>Jinja2 (Python):</strong> Relies on Python&#39;s introspection: <code>__globals__</code>, <code>__subclasses__</code>, <code>lipsum.__globals__[&#39;os&#39;]</code>.</li><li><strong>Twig (PHP):</strong> In modern Twig, sandboxes restrict tags, filters, and methods via strict allow-lists. Older versions permitted <code>_self.env</code> registration.</li><li><strong>FreeMarker (Java):</strong> Uses <code>?api</code>, <code>?new()</code>, and Java reflection. <code>api_builtin_enabled=true</code> must often be present for deep object access.</li><li><strong>Velocity (Java):</strong> Employs <code>$class.inspect()</code> and reflection to load Java&#39;s <code>Runtime</code> class.</li><li><strong>Thymeleaf (Spring / Java):</strong> Evaluates SpEL (Spring Expression Language) using <code>__${...}__</code> preprocessing, giving access to Spring beans and the application context.</li><li><strong>Handlebars (JS):</strong> Logic-less by design, but vulnerable when custom helpers are defined or when combined with prototype pollution gadgets.</li></ul><p>The exact engine version is critical: minor framework patches frequently remove specific classes or close reflection loopholes.</p></details><div class="wd-callout wd-callout--warn"><p><strong>🛡️ Defensive Blueprint: How to Prevent SSTI</strong></p><ol><li><strong>Keep Templates Static:</strong> Never concatenate, interpolate, or format user input into template source code before compilation. Templates should reside in static files on disk.</li><li><strong>Pass Data Exclusively via Context:</strong> Supply all dynamic user data as parameters to the template render call. The engine will automatically escape it as harmless text.</li><li><strong>Choose Logic-Less Engines:</strong> Consider logic-less template systems like Mustache for user-facing template customization, which cannot evaluate arbitrary expressions.</li><li><strong>Run in Isolated Processes:</strong> If users must be allowed to edit template files, render them inside restricted, unprivileged sandbox containers with no network or filesystem permissions.</li></ol></div>',2)),s(r,{"topic-id":"server-side-template-injection",label:"Mark SSTI complete"})])}const y=l(p,[["render",g]]);export{w as __pageData,y as default};
